window.GuanwuVoices=(()=>{
 let preview=null,activePreview='';
 function stopPreview(){if(preview){preview.pause();preview.removeAttribute('src');preview.load();preview=null}activePreview='';document.querySelectorAll('[data-voice-preview]').forEach(b=>b.textContent='▷ 试听')}
 function settings(){const selected=player.voice;dialog(`<div class="eyebrow">THE VOICE BESIDE YOU</div><h2 id="modal-title">让讲述，合你的心意。</h2><p class="voice-setting-intro">选择一位同行的声音。音量已统一，选择会保存在当前浏览器；可随时在播放器中切换。</p><div class="voice-pack-list">${GUANWU_VOICE_PACKS.packs.map(p=>`<article class="voice-pack ${selected===p.id?'selected':''}"><button class="voice-select" data-voice-select="${p.id}" aria-pressed="${selected===p.id}"><span class="voice-orb ${p.id}" aria-hidden="true">${p.id==='yunxi'?'◌':'◍'}</span><strong>${esc(p.name)}<small>${esc(p.description)}</small></strong><b>${selected===p.id?'✓':'＋'}</b></button><button class="outline-btn" data-voice-preview="${p.id}">▷ 试听</button></article>`).join('')}</div><p class="tiny-note">三套均为 AI 合成普通话，不是真人或名人录音。已有语音的章节与世界遗产简介支持切换；标注“阅读”的章节暂不提供音频。离线保存只下载当前选择的声音。</p>`)}
 document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-voice-settings')){settings();return}if(b.dataset.voiceSelect){stopPreview();await player.setVoice(b.dataset.voiceSelect);settings();toast('讲述声音已设为'+GUANWU_VOICE_PACKS.packs.find(p=>p.id===player.voice).name)}if(b.dataset.voicePreview){const id=b.dataset.voicePreview;if(id===activePreview){stopPreview();return}stopPreview();player.audio.pause();player.save();const p=GUANWU_VOICE_PACKS.packs.find(p=>p.id===id);preview=new Audio(p.preview);activePreview=id;b.textContent='Ⅱ 停止试听';preview.addEventListener('ended',stopPreview);preview.addEventListener('error',()=>{stopPreview();toast('试听暂未加载，请联网后重试。')});try{await preview.play()}catch{stopPreview();toast('点击试听继续，或检查网络。')}}});
 document.addEventListener('change',e=>{if(e.target.id==='audio-voice'){stopPreview();player.setVoice(e.target.value)}});
 document.addEventListener('click',e=>{if(e.target.closest('[data-play],[data-audio="toggle"],[data-heritage-listen]'))stopPreview()});
 document.getElementById('modal').addEventListener('close',stopPreview);window.addEventListener('pagehide',stopPreview);
 return {settings,stopPreview};
})();
